/* Dressed For Space - Drums (Speculative Score Draft) */

// --- Synths ---
const kick = new Tone.MembraneSynth({
  pitchDecay: 0.04,
  octaves: 5,
  envelope: { attack: 0.001, decay: 0.4, sustain: 0 },
  volume: -2,
}).toDestination();
const snare = new Tone.NoiseSynth({
  noise: { type: 'white' },
  envelope: { attack: 0.001, decay: 0.18, sustain: 0 },
}).chain(new Tone.Filter(1500, 'bandpass', -12), Tone.Destination);
snare.volume.value = -8;

const offbeatHat = new Tone.MetalSynth({
  frequency: 400,
  harmonicity: 7, 
  modulationIndex: 20,
  envelope: { attack: 0.001, decay: 0.2, sustain: 0 },
  volume: -18,
}).toDestination();

// --- Patterns ---
const kickPart = new Tone.Sequence((time, note) => {
  kick.triggerAttackRelease(note, '8n', time);
}, ['G1', null, 'G1', null], '4n').start(0);

const snarePart = new Tone.Sequence((time) => {
  snare.triggerAttack(time);
}, [null, 'x', null, 'x'], '4n').start(0);

// To build the track, create Tone.Part for each track's `steps`.
// Use Part.start(time) and Part.stop(time) at section boundaries
// to bring instruments in and out, building arrangement dynamically.

/* Speculative Score Draft for Tone.js */

// Tempo and global FX
Tone.Transport.bpm.value = 133;
const reverb = new Tone.Reverb({
  decay: 4.5,
  wet: 0.8,
  preDelay: 0.01
}).toDestination();

// Lead Vocal Synth
const leadSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fatsawtooth', count: 5, spread: 30 },
  envelope: { attack: 0.05, decay: 0.4, sustain: 0.7, release: 0.8 },
  filter: { type: 'lowpass', frequency: 3500, Q: 2.5 },
  volume: -9
});
const chorus = new Tone.Chorus(4, 2.5, 0.6).start();
const drive = new Tone.Distortion(0.1);
leadSynth.connect(chorus).connect(drive).connect(reverb);
// Pattern: e.g., ['E3', null, 'E3', null, 'G3', 'A3', 'B3', null, 'A3', 'G3', 'E3', null, null, null, null, null] on a '16n' grid.

// Reverb Pad Synth
const padSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'triangle' },
  envelope: { attack: 2.5, decay: 1, sustain: 0.8, release: 4 },
  filter: { type: 'lowpass', frequency: 1000 },
  volume: -22
}).connect(reverb);
// Pattern: Play sustained Em chords, e.g., ['E3 G3 B3'] on a '1m' grid.

/* Dressed For Space - Other Stem - Speculative Score Draft */

// Global setup: tempo and key
Tone.Transport.bpm.value = 133;
const key = 'E minor';

// FX Chain: create a large space
const chorus = new Tone.Chorus(4, 2.5, 0.7).toDestination().start();
const reverb = new Tone.Reverb({
  decay: 4.5,
  preDelay: 0.01,
  wet: 0.6
}).connect(chorus);

// Foundation Pad: Use PolySynth with a fat oscillator for width.
const foundationPad = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fatsawtooth', count: 7, spread: 30 },
  envelope: { attack: 0.5, decay: 0.2, sustain: 0.9, release: 1.5 },
  filter: { type: 'lowpass', frequency: 3500, Q: 1.5 },
  volume: -12
}).connect(reverb);

// Arp Lead: A standard Synth with a faster envelope and resonant filter.
const arpLead = new Tone.Synth({
  oscillator: { type: 'sawtooth' },
  envelope: { attack: 0.01, decay: 0.3, sustain: 0.5, release: 0.4 },
  filter: { type: 'lowpass', frequency: 5000, Q: 2.2 },
  volume: -9
}).connect(reverb);

// Example chord progression in E minor (i-VI-III-VII)
const progression = ['Em', 'C', 'G', 'D'];

// Example loop: play arpeggios and chords
new Tone.Loop(time => {
  // Trigger arpeggio notes from the chords (e.g., E minor)
  arpLead.triggerAttackRelease('E5', '16n', time);
  arpLead.triggerAttackRelease('G5', '16n', time + Tone.Time('16n').toSeconds());
  arpLead.triggerAttackRelease('B5', '16n', time + Tone.Time('8n').toSeconds());
  // ... and so on for a full bar pattern.

  // Trigger the pad chord at the start of the bar
  foundationPad.triggerAttackRelease(['E3', 'G3', 'B3'], '1m', time);
}, '1m').start(0);

Tone.Transport.start();

/* Speculative Score-Draft Starter */

// The track features two main states for one bassline.
// Use Tone.Part to sequence the notes and Tone.Transport.scheduleRepeat
// to automate the synth parameters between sections.

const subduedBass = new Tone.MonoSynth({
  oscillator: { type: 'fatsawtooth', count: 3, spread: 20 },
  envelope: { attack: 0.01, decay: 0.2, sustain: 0.2, release: 0.2 },
  filter: { type: 'lowpass', frequency: 450, Q: 2 },
  drive: 0.2,
  volume: -9
}).toDestination();

const drivenBass = new Tone.MonoSynth({
  oscillator: { type: 'fatsawtooth', count: 5, spread: 30 },
  envelope: { attack: 0.01, decay: 0.2, sustain: 0.3, release: 0.2 },
  filter: { type: 'lowpass', frequency: 900, Q: 3 },
  drive: 0.5,
  volume: -6
}).toDestination();

const bassPattern = [
  'A2', 'A2', 'G2', 'G2', 'C3', 'C3', 'E2', 'E2',
  'A2', 'A2', 'G2', 'G2', 'C3', 'C3', 'D3', 'D3'
];

// A simplified example of switching between the two synth sounds.
let currentSynth = subduedBass;
let noteIndex = 0;
const part = new Tone.Loop(time => {
  currentSynth.triggerAttackRelease(bassPattern[noteIndex % bassPattern.length], '8n', time);
  noteIndex++;
}, '8n').start(0);

// Use schedule to swap synths at section boundaries.
Tone.Transport.scheduleOnce((time) => {
  currentSynth = drivenBass;
}, '16m'); // Approx 51.3s at 133 BPM
